// sunset: a small PNG data: URI (src/pictures.js)
function Demo() {
  const saved = $signal($active(), false);
  return (
    <Card bordered shadow="sm" w={300}>
      <Card.Media>
        <Image source={sunset} h={96} label="Evening light over the harbor" />
      </Card.Media>
      <Text size="xs" fg="indigo" fontWeight={600}>Fri 14 Nov, 20:30</Text>
      <Text size="lg" fontWeight="bold">Harbor Lights Quartet</Text>
      <Row gap="xs" mt="xs">
        <Badge variant="soft" color="indigo">Row F</Badge>
        <Badge variant="soft" color="amber">Seat 12</Badge>
      </Row>
      <Card.Rule />
      <Row justify="between" align="center">
        <Text size="sm" fg="quiet">Admits one</Text>
        <Button variant="soft" size="xs" onPress={() => $write(saved, !$read(saved))}>
          {() => ($read(saved) ? 'In your wallet' : 'Add to wallet')}
        </Button>
      </Row>
    </Card>
  );
}`,view:()=>{let e=T(C(),!1);return i(rr,{bordered:!0,shadow:"sm",w:300},i(rr.Media,null,i(or,{source:Xr,h:96,label:"Evening light over the harbor"})),i(z,{size:"xs",fg:"indigo",fontWeight:600},"Fri 14 Nov, 20:30"),i(z,{size:"lg",fontWeight:"bold"},"Harbor Lights Quartet"),i(N,{gap:"xs",mt:"xs"},i(Ke,{variant:"soft",color:"indigo"},"Row F"),i(Ke,{variant:"soft",color:"amber"},"Seat 12")),i(rr.Rule,null),i(N,{justify:"between",align:"center"},i(z,{size:"sm",fg:"quiet"},"Admits one"),i(V,{variant:"soft",size:"xs",onPress:()=>v(e,!g(e))},()=>g(e)?"In your wallet":"Add to wallet")))},height:290},{title:"Ruled rows and a picture on top",code:`
